<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {tr,language} from '../composables/i18n'
import {Plus,Search,Clock3,MoreHorizontal,ChevronRight,Users,FileText,CalendarClock,Laptop,RotateCw,Bell,Pencil,Trash2,Play,Code2,SquareTerminal,Database,Bug,History as HistoryIcon} from 'lucide-vue-next'
import AppDialog from '../components/AppDialog.vue'
import PageHeader from '../components/PageHeader.vue'
import ProviderIcon from '../components/ProviderIcon.vue'
import ToggleSwitch from '../components/ToggleSwitch.vue'
import TaskModal from '../components/TaskModal.vue'
import TaskContextMenu from '../components/TaskContextMenu.vue'
import PaginationBar from '../components/PaginationBar.vue'
import Select from '../components/Select.vue'
import {store,action} from '../stores/store'
import {api,formatDate,providerName} from '../services/api'
import {relativeTime,scheduleLabel} from '../services/presentation'
import {stateLabel} from '../types/states'
import type {Task,CreateTaskRequest} from '../types'
const route=useRoute(),router=useRouter(),search=ref(String(route.query.q||'')),provider=ref('all'),status=ref('all'),selectedId=ref(''),selectedRows=ref<string[]>([]),detailId=ref(''),editing=ref(false),editTask=ref<Task>(),deleting=ref<Task>(),deletingBusy=ref(false),busyIds=ref(new Set<string>())
const page=ref(1),pageSize=ref(10),menu=ref<{task:Task;x:number;y:number;id:number}>();let menuId=0
const providerOptions=computed(()=>[{value:'all',label:tr('全部提供商')},{value:'codex',label:'Codex'},{value:'claude_code',label:'Claude Code'}])
const all=computed(()=>store.tasks.filter(t=>t.state!=='cancelled'))
const providerTasks=computed(()=>all.value.filter(t=>provider.value==='all'||t.request.conversation.provider===provider.value))
const filtered=computed(()=>providerTasks.value.filter(t=>(status.value==='all'||status.value==='enabled'&&t.state==='scheduled'||status.value==='waiting'&&['needs_review','blocked_approval'].includes(t.state)||status.value===t.state)&&[t.request.title,t.request.prompt,t.request.conversation.cwd].some(v=>v.toLowerCase().includes(search.value.toLowerCase()))))
const totalPages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize.value)))
const pageRows=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value))
const selected=computed(()=>all.value.find(t=>t.id===detailId.value))
const selectionCount=computed(()=>filtered.value.filter(t=>selectedRows.value.includes(t.id)).length)
const pageSelected=computed(()=>!!pageRows.value.length&&pageRows.value.every(t=>selectedRows.value.includes(t.id)))
const pagePartial=computed(()=>!pageSelected.value&&pageRows.value.some(t=>selectedRows.value.includes(t.id)))
watch([search,provider,status,pageSize],()=>{page.value=1;menu.value=undefined},{flush:'sync'})
watch(totalPages,count=>{page.value=Math.min(page.value,count)})
watch([detailId,filtered],([id,tasks])=>{if(!id)return;const index=tasks.findIndex(task=>task.id===id);if(index>=0)page.value=Math.floor(index/pageSize.value)+1})
watch(all,tasks=>{const ids=new Set(tasks.map(t=>t.id));selectedRows.value=selectedRows.value.filter(id=>ids.has(id));if(menu.value&&!ids.has(menu.value.task.id))menu.value=undefined})
watch(()=>route.query.task,id=>{if(typeof id==='string'){provider.value='all';status.value='all';search.value='';selectedId.value=id;detailId.value=id}},{immediate:true})
function toggleSelection(id:string){selectedId.value=id;selectedRows.value=selectedRows.value.includes(id)?selectedRows.value.filter(value=>value!==id):[...selectedRows.value,id]}
function selectPage(){const ids=new Set(selectedRows.value);for(const task of pageRows.value){if(pageSelected.value)ids.delete(task.id);else ids.add(task.id)}selectedRows.value=[...ids]}
function showDetails(task:Task){detailId.value=task.id;selectedId.value=task.id;menu.value=undefined}
function closeDetails(){detailId.value='';if(typeof route.query.task==='string'){const query={...route.query};delete query.task;void router.replace({query})}}
function edit(task?:Task){editTask.value=task;closeDetails();editing.value=true;menu.value=undefined}
function askDelete(task:Task){deleting.value=task;closeDetails();menu.value=undefined}
function openMenu(event:MouseEvent|KeyboardEvent,task:Task){const target=event.currentTarget as HTMLElement,rect=target.getBoundingClientRect();target.focus();selectedId.value=task.id;const pointer=event instanceof MouseEvent&&(event.clientX!==0||event.clientY!==0);menu.value={task,x:pointer?event.clientX:rect.right,y:pointer?event.clientY:rect.bottom,id:++menuId}}
async function toggle(task:Task,enabled:boolean){if(busyIds.value.has(task.id))return;busyIds.value.add(task.id);try{await action(()=>api.pause(task.id,!enabled),enabled?'任务已恢复':'任务已暂停',`task:${task.id}:scheduling`)}finally{busyIds.value.delete(task.id)}}
async function menuAction(value:'details'|'edit'|'run'|'pause'|'delete'){
 const id=menu.value?.task.id,task=all.value.find(value=>value.id===id);menu.value=undefined;if(!task)return
 if(value==='details')showDetails(task)
 else if(value==='edit')edit(task)
 else if(value==='delete')askDelete(task)
 else if(value==='pause'&&['scheduled','paused'].includes(task.state))await toggle(task,task.state==='paused')
 else if(value==='run'&&task.state==='scheduled'&&!busyIds.value.has(task.id)){busyIds.value.add(task.id);try{await action(()=>api.run(task.id),tr('执行器已启动，请查看最终结果'),`task:${task.id}:execution`)}finally{busyIds.value.delete(task.id)}}
}
async function patch(task:Task,change:Partial<CreateTaskRequest>){await action(()=>api.saveTask({...task.request,...change},task.id),'操作已完成',`task:${task.id}:settings`)}
async function remove(){if(!deleting.value||deletingBusy.value)return;deletingBusy.value=true;try{await action(()=>api.cancel(deleting.value!.id),'任务已取消，历史记录保留',`task:${deleting.value!.id}:cancellation`);if(!all.value.some(task=>task.id===deleting.value?.id))deleting.value=undefined}finally{deletingBusy.value=false}}
const icons=[Code2,FileText,SquareTerminal,Database,Bell,Bug],colors=['blue','purple','blue','green','orange','pink']
function visual(task:Task){const index=Array.from(task.id).reduce((sum,c)=>sum+c.charCodeAt(0),0)%icons.length;return {icon:icons[index],color:colors[index]}}
function taskStatus(task:Task){return task.state==='scheduled'?tr('已启用'):task.state==='paused'?tr('暂停中'):['needs_review','blocked_approval'].includes(task.state)?tr('等待恢复'):stateLabel(task.state)}
function recurrenceHint(task:Task){return task.request.recurrence?.kind==='every_hours'?tr('间隔执行'):task.request.recurrence?.kind==='daily'?tr('每天'):task.request.recurrence?.kind==='weekly'?tr('每周'):tr('仅执行一次')}
const ended=(task:Task)=>['succeeded','failed','expired','completed_unverified'].includes(task.state)
function nextDate(task:Task){if(ended(task))return '—';const value=new Date(task.request.scheduled_at_utc);return Number.isNaN(value.getTime())?'—':new Intl.DateTimeFormat(language.value,{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(value)}
function nextHint(task:Task){return ended(task)?tr('已结束'):task.state==='paused'?tr('已暂停'):['needs_review','blocked_approval'].includes(task.state)?tr('等待确认'):relativeTime(task.request.scheduled_at_utc,store.now)}
</script>
<template><div class="task-page">
 <PageHeader :title="tr('任务管理')" :subtitle="tr('管理自动继续、定时运行和恢复后的执行任务')"/>
 <div class="task-toolbar task-table-toolbar">
  <div class="input-icon task-search"><Search/><input v-model="search" :placeholder="tr('搜索任务名称或描述…')" :aria-label="tr('搜索任务名称或描述')"></div>
  <Select class="task-provider-filter" v-model="provider" :options="providerOptions" :aria-label="tr('任务提供商')" :placeholder="tr('选择提供商')"/>
  <div class="task-status-tabs"><button v-for="item in [{id:'enabled',label:tr('已启用'),states:['scheduled']},{id:'paused',label:tr('暂停中'),states:['paused']},{id:'waiting',label:tr('等待恢复'),states:['needs_review','blocked_approval']}]" :key="item.id" :class="{active:status===item.id}" :aria-pressed="status===item.id" @click="status=status===item.id?'all':item.id"><span>{{item.label}}</span><small>{{providerTasks.filter(task=>item.states.includes(task.state)).length}}</small></button></div>
  <button class="primary new-button" @click="edit()"><Plus/>{{tr('新建任务')}}</button>
 </div>
 <section class="panel task-table-panel">
  <div class="table-scroll"><table class="task-table" :aria-label="tr('定时任务列表')"><thead><tr><th class="check-cell"><input type="checkbox" :aria-label="tr('选择本页全部任务')" :checked="pageSelected" :indeterminate="pagePartial" :disabled="!pageRows.length" @change="selectPage"></th><th>{{tr('任务名称')}}</th><th>{{tr('提供商')}}</th><th>{{tr('执行计划')}}</th><th>{{tr('下次运行时间')}}</th><th>{{tr('状态')}}</th><th>{{tr('启用')}}</th><th class="action-cell">{{tr('操作')}}</th></tr></thead>
  <tbody><tr v-for="task in pageRows" :key="task.id" class="task-row" :class="{selected:selectedRows.includes(task.id)||selectedId===task.id}" tabindex="0" @click="toggleSelection(task.id)" @keydown.space.self.prevent="toggleSelection(task.id)" @keydown.enter.self.prevent="showDetails(task)" @contextmenu.prevent="openMenu($event,task)" @keydown.shift.f10.prevent="openMenu($event,task)" @keydown.context-menu.prevent="openMenu($event,task)">
   <td class="check-cell" @click.stop><input type="checkbox" :aria-label="tr('选择任务：')+task.request.title" :checked="selectedRows.includes(task.id)" @change="toggleSelection(task.id)"></td>
   <td class="task-name-cell"><span class="task-kind-icon" :class="visual(task).color" aria-hidden="true"><component :is="visual(task).icon"/></span><div><h3 :title="task.request.title">{{task.request.title}}</h3><p :title="task.request.prompt">{{task.request.prompt}}</p></div></td>
   <td><span class="task-provider-pill" :class="task.request.conversation.provider"><ProviderIcon :provider="task.request.conversation.provider" size="small"/>{{providerName(task.request.conversation.provider)}}</span></td>
   <td class="task-schedule-cell"><strong>{{scheduleLabel(task.request)}}</strong><small>{{recurrenceHint(task)}}</small></td>
   <td class="task-next-cell"><strong>{{nextDate(task)}}</strong><small>{{nextHint(task)}}</small></td>
   <td><span class="badge task-state-badge" :class="task.state"><i class="status-dot"/>{{taskStatus(task)}}</span></td>
   <td @click.stop><ToggleSwitch :label="task.request.title+tr(' 启用')" :model-value="task.state==='scheduled'" :disabled="busyIds.has(task.id)||!['scheduled','paused'].includes(task.state)" @update:model-value="value=>toggle(task,value)"/></td>
   <td class="action-cell" @click.stop><button class="icon-button task-menu-trigger" :aria-label="task.request.title+tr(' 操作')" aria-haspopup="menu" @click="openMenu($event,task)"><MoreHorizontal/></button></td>
  </tr></tbody></table>
  <div v-if="!filtered.length" class="empty-state"><CalendarClock/><h2>{{all.length?tr('没有匹配的任务'):tr('还没有定时任务')}}</h2><p>{{tr('选择已有会话，创建第一个定时任务。')}}</p><button class="primary" @click="edit()"><Plus :size="17"/>{{tr('新建任务')}}</button></div></div>
  <PaginationBar class="task-pagination" subject="tasks" :total="filtered.length" :selected="selectionCount" v-model:page="page" v-model:page-size="pageSize"/>
 </section>
 <TaskContextMenu v-if="menu" :key="menu.id" :x="menu.x" :y="menu.y" :state="menu.task.state" :busy="busyIds.has(menu.task.id)" @action="menuAction" @close="menu=undefined"/>
 <AppDialog v-if="selected" :title="tr('任务详情')" :description="selected.request.title" wide panel-class="task-details-dialog" @close="closeDetails"><div class="task-detail"><div class="detail-heading"><ProviderIcon :provider="selected.request.conversation.provider"/><div><h3>{{selected.request.title}}</h3><span class="badge" :class="selected.state"><i class="status-dot"/>{{stateLabel(selected.state)}}</span></div><button class="icon-button" :title="tr('编辑所选任务')" @click="edit(selected)"><MoreHorizontal/></button></div><label class="detail-caption">{{tr("AI 提供商")}}</label><button class="detail-input" @click="edit(selected)"><Users/><ProviderIcon :provider="selected.request.conversation.provider" size="small"/><span>{{providerName(selected.request.conversation.provider)}}</span><ChevronRight/></button><label class="detail-caption">{{tr("会话标题")}}</label><button class="detail-input" @click="edit(selected)"><FileText/><span>{{selected.request.conversation.title}}</span><ChevronRight/></button><label class="detail-caption">{{tr("定时设置")}}</label><div class="detail-section"><button class="detail-row" @click="edit(selected)"><Clock3/><span>{{tr("运行时间")}}</span><strong>{{scheduleLabel(selected.request)}}</strong><ChevronRight/></button><div class="detail-row"><Clock3/><span>{{tr("下次运行")}}</span><div><strong>{{relativeTime(selected.request.scheduled_at_utc,store.now)}}</strong><small>{{formatDate(selected.request.scheduled_at_utc)}}</small></div></div></div><label class="detail-caption">{{tr("任务提示词")}}</label><button class="detail-section prompt-preview" @click="edit(selected)"><FileText/><span>{{selected.request.prompt}}</span><ChevronRight/></button><label class="detail-caption">{{tr("高级设置")}}</label><div class="detail-section detail-options"><div><Laptop/><span><strong>{{tr("从睡眠中唤醒电脑")}}</strong><small>{{tr("在任务开始前尝试唤醒设备")}}</small></span><ToggleSwitch :label="tr('从睡眠中唤醒电脑')" :model-value="selected.request.wake_to_run" :disabled="selected.state!=='scheduled'" @update:model-value="v=>patch(selected!,{wake_to_run:v})"/></div><div><RotateCw/><span><strong>{{tr("补跑错过的任务")}}</strong><small>{{tr("恢复后在 12 小时内自动补跑")}}</small></span><ToggleSwitch :label="tr('补跑错过的任务')" :model-value="selected.request.catch_up_policy==='run_on_next_start'" :disabled="selected.state!=='scheduled'" @update:model-value="v=>patch(selected!,{catch_up_policy:v?'run_on_next_start':'ask'})"/></div><div><Bell/><span><strong>{{tr("任务完成时通知我")}}</strong><small>{{tr("通过右上角弹窗提醒执行结果")}}</small></span><ToggleSwitch :label="tr('任务完成时通知我')" :model-value="selected.request.notify" :disabled="selected.state!=='scheduled'" @update:model-value="v=>patch(selected!,{notify:v})"/></div></div><p v-if="selected.message" class="field-message">{{tr(selected.message)}}</p><div class="detail-actions"><button @click="edit(selected)"><Pencil :size="19"/>{{tr("编辑任务")}}</button><button class="danger" @click="askDelete(selected)"><Trash2 :size="19"/>{{tr("删除任务")}}</button></div><RouterLink class="detail-history" to="/history">{{tr("查看运行历史")}} <HistoryIcon :size="15"/></RouterLink></div></AppDialog>
 <TaskModal v-if="editing" :task="editTask" @close="editing=false" @saved="editing=false"/><AppDialog v-if="deleting" :title="tr('删除任务')" :description="tr('删除前请确认以下任务')" panel-class="danger-dialog" :busy="deletingBusy" @close="deleting=undefined"><template #icon><Trash2 :size="23"/></template><div class="dialog-selected-item"><ProviderIcon :provider="deleting.request.conversation.provider"/><div><strong>{{deleting.request.title}}</strong><p>{{scheduleLabel(deleting.request)}}</p></div></div><p>{{tr("删除后，此任务将不再自动执行，已有运行历史会保留。正在运行的任务将请求停止。")}}</p><template #footer><button :disabled="deletingBusy" @click="deleting=undefined">{{tr("保留任务")}}</button><button class="danger" :disabled="deletingBusy" @click="remove"><Trash2 :size="16"/>{{tr("确认删除")}}</button></template></AppDialog></div></template>

<style scoped>
.task-page{height:calc(100dvh - var(--titlebar-height) - 48px);min-height:440px;display:flex;flex-direction:column}.task-page>.page-heading,.task-table-toolbar{flex-shrink:0}
.task-page .page-heading{min-height:60px;margin-bottom:16px}.task-page :deep(.page-heading h1){font-size:28px}.task-page :deep(.page-heading p){font-size:13px;margin-top:5px}
.task-table-toolbar{gap:9px;flex-wrap:wrap;margin-bottom:16px;align-items:center}.task-table-toolbar .task-search{order:0;margin-left:0;flex:1;min-width:180px;max-width:270px;width:auto;height:40px}.task-search input{font-size:12px;padding:10px 8px}.task-search>svg{width:17px;height:17px}
.task-provider-filter{width:156px;flex-shrink:0}.task-provider-filter :deep(.select-control){height:40px;min-height:40px;font-size:12px}.task-status-tabs{display:flex;gap:5px;align-items:center}.task-status-tabs button{font-size:12px;min-height:38px;padding:6px 9px;gap:6px;white-space:nowrap;background:var(--surface);border-color:var(--border)}.task-status-tabs small{font-size:10px;background:var(--tint);border-radius:5px;min-width:17px;text-align:center;padding:0 3px;color:var(--muted)}.task-status-tabs .active{color:var(--primary);border-color:#a7ceff;background:var(--tint);box-shadow:inset 0 0 0 1px #fff8}.task-status-tabs{border-left:1px solid var(--border);padding-left:9px;gap:4px}.task-status-tabs button{border-radius:99px;padding:5px 8px;min-height:34px}.task-table-toolbar .new-button{margin-left:auto;min-width:108px;min-height:40px;font-size:14px;padding:8px 12px;border-radius:9px;gap:7px}.task-table-toolbar .new-button>svg{width:18px;height:18px}
.task-table-panel{overflow:hidden;min-height:180px;flex:1;display:flex;flex-direction:column;border-radius:12px}.task-table-panel>.table-scroll{flex:1;min-height:0}.task-table{width:100%;min-width:890px;table-layout:fixed;font-size:12px}.task-table thead{background:var(--tint)}.task-table th{padding:13px 11px;color:var(--muted);font-size:12px;position:sticky;top:0;z-index:1;background:var(--tint)}.task-table th+th:not(.check-cell):before{content:'';position:absolute;left:0;top:13px;bottom:13px;width:1px;background:var(--border);opacity:.5}.task-table td{height:71px;padding:12px 11px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text)}.task-table .check-cell{width:34px;padding-left:12px;padding-right:4px}.task-table input[type=checkbox]{width:16px;height:16px;cursor:pointer}.task-table th:nth-child(3){width:118px}.task-table th:nth-child(4){width:120px}.task-table th:nth-child(5){width:150px}.task-table th:nth-child(6){width:86px}.task-table th:nth-child(7){width:63px}.task-table .action-cell{width:46px;padding-left:3px;padding-right:7px;text-align:center}
.task-row{cursor:pointer;outline-offset:-3px}.task-row:hover td{background:var(--tint)}.task-row.selected td{background:color-mix(in srgb,var(--primary) 9%,var(--surface));border-top:1px solid #80b8ff;border-bottom-color:#80b8ff}.task-row.selected td:first-child{box-shadow:inset 1px 0 #80b8ff}.task-row.selected td:last-child{box-shadow:inset -1px 0 #80b8ff}.task-table .task-name-cell{position:relative;padding-left:62px}.task-kind-icon{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:34px;height:36px;display:grid;place-items:center;border-radius:10px;color:#0078ff;background:#edf6ff}.task-kind-icon>svg{width:22px;height:22px}.task-kind-icon.purple{color:#8a3cff;background:#f2ebff}.task-kind-icon.green{color:#00a87d;background:#e4faf2}.task-kind-icon.orange{color:#f58224;background:#fff2e5}.task-kind-icon.pink{color:#ff3c72;background:#fff0f5}.task-name-cell h3{font-size:14px;font-weight:600;line-height:1.5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:0}.task-name-cell p{font-size:12px;line-height:1.5;margin-top:3px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.task-provider-pill{display:inline-flex;align-items:center;gap:6px;font-size:11px;white-space:nowrap;padding:3px 6px;border-radius:8px;background:var(--tint)}.task-provider-pill :deep(.provider-mark){width:19px;height:19px;border-radius:5px;background:transparent;box-shadow:none}.task-provider-pill :deep(.provider-mark>img){width:94%;height:94%}.task-schedule-cell strong,.task-next-cell strong{font-size:12px;font-weight:400;white-space:nowrap;display:block}.task-schedule-cell small,.task-next-cell small{font-size:11px;line-height:1.5;color:var(--muted);display:block;margin-top:3px}.task-state-badge{font-size:11px;padding:4px 7px;gap:5px;white-space:nowrap}.task-state-badge .status-dot{width:7px;height:7px}.task-state-badge.paused{background:#e6f1ff;color:#1878ee}.task-state-badge.paused .status-dot{background:#1878ee}.task-state-badge.needs_review,.task-state-badge.blocked_approval{background:#fff2d5;color:#c48a16}.task-state-badge.needs_review .status-dot,.task-state-badge.blocked_approval .status-dot{background:#f0a21c}.task-menu-trigger{min-height:32px;width:32px;padding:5px;color:#5375ad;border-radius:9px}.task-menu-trigger:focus-visible,.task-row.selected .task-menu-trigger{background:var(--tint);color:var(--primary)}.task-table :deep(.toggle-switch){width:38px;min-width:38px;height:22px;min-height:22px;padding:3px}.task-table :deep(.toggle-switch span){width:16px;height:16px}.task-table :deep(.toggle-switch.on span){transform:translateX(16px)}
.task-detail{padding:24px 28px;border:0;background:transparent;box-shadow:none;max-width:none}.task-detail .detail-actions{margin-top:18px}.task-detail .detail-heading>div{min-width:0}.task-detail .detail-heading h3{overflow-wrap:anywhere}.task-detail .detail-input{width:100%}
@media(max-width:1100px){.task-table-toolbar .task-search{min-width:170px;max-width:none;flex-basis:220px}.task-status-tabs{order:2;border:0;padding-left:0}.task-table-toolbar .new-button{order:1}.task-table-toolbar .task-provider-filter{margin-left:auto}}
@media(max-width:640px){.task-page :deep(.page-heading h1){font-size:25px}.task-table-toolbar .task-search{flex-basis:100%;max-width:none}.task-table-toolbar .task-provider-filter{margin-left:0}.task-table-toolbar .new-button{min-width:98px;font-size:12px}.task-detail{padding:18px}}
</style>
